// ---- tahmin yardımcıları ----
function tahminA(A,B,def){if(tot(A)<1)return 'asker seç';const BB={};for(const k in (B||{}))if(U[k]&&B[k]>0)BB[k]=B[k];if(tot(BB)<1)return 'kolay kazanırsın';const oA=mA,oB=mB,oHA=hA,oHB=hB;const cm=(1+.02*Math.min(S.cr||0,60))*(1+.04*S.sk.war)*(1+.02*(S.rel||0))*(1+(S.won?(S.won.zafer||0)*.07:0))*(1+crB('savas'))*komMul();mA=(1+.08*S.lv.tatk)*(1+vb())*cm;hA=(1+.08*S.lv.tdef)*(1+vb())*cm;mB=hB=def;let r;try{const fr=fight(Object.assign({},A),Object.assign({},BB),{}),a=fr[0],b=fr[1],sa=tot(a),sb=tot(b);if(sb<.5&&sa>=.5)r=sa/tot(A)>.65?'kolay kazanırsın':'kazanırsın';else r=sb<tot(BB)*.35?'çok zorlu':'kaybedersin';}finally{mA=oA;mB=oB;hA=oHA;hB=oHB;}return r;}
function wEstCol(t){return /kolay/.test(t)?'#3C8A5A':/kazan/.test(t)?'#5E9C4E':/zorlu/.test(t)?'#C48A2A':/kaybed/.test(t)?'#B9473A':'#7D8A86';}
/* Otomatik ordu: düşmana göre yeterli asker sayısını bulur (tahmin motoruyla), küçük bir güvenlik payı ekler */
function autoOrdu(B,def,risk){const H=wHomeArmy(),of=tot(H);if(of<1)return null;const win=function(r){return r==='kolay kazanırsın'||r==='kazanırsın'};const full=tahminA(H,B,def);
 const put=function(A){for(const k in U)sel[k]=Math.min(A[k]||0,S.ar[k]||0);};
 if(!win(full)){put(H);return {m:'full',r:full,n:of,of:of};}
 const goal=risk?'kazanırsın':full;const good=function(A){if(risk){const d=tahminD(A,B,def);return win(d.r)&&d.lost<=d.sent*.55;}const r=tahminA(A,B,def);return goal==='kolay kazanırsın'?r===goal:win(r)};
 const sc=function(f){const A={};for(const k in H){const n=Math.min(H[k],Math.ceil(H[k]*f));if(n>0)A[k]=n}return A};
 let lo=0,hi=1;for(let i=0;i<14&&hi-lo>.002;i++){const m=(lo+hi)/2;if(good(sc(m)))hi=m;else lo=m;}
 const A=sc(hi);
 /* birim birim kırp: gereksiz türleri azalt (karşı birimler kendiliğinden öne çıkar) */
 Object.keys(A).sort(function(a,b){return A[b]-A[a]}).forEach(function(k){let l=0,h=A[k];while(l<h){const m=Math.floor((l+h)/2),T=Object.assign({},A);if(m>0)T[k]=m;else delete T[k];if(tot(T)>=1&&good(T))h=m;else l=m+1;}if(h>0)A[k]=h;else delete A[k];});
 /* güvenlik payı: %20 (en az +1) */
 if(!risk)for(const k in A)A[k]=Math.min(H[k],Math.ceil(A[k]*1.2)+(A[k]<10?1:0));
 if(!good(A))for(const k in H)A[k]=H[k];
 put(A);return {m:risk?'risk':'auto',r:tahminA(A,B,def),n:tot(A),of:of};}
